save(430,dict(paragraphs=["Veena Karmachandani, also published as Veena Karamchandani, is a Jaipur-based writer working in Sindhi and Hindi. Her place in contemporary Sindhi writing is reflected in Sahitya Akademi's account of women writers and in a Kachchh University poetry syllabus, which includes her Maau ji Saugaat. Her contributor note also identifies fiction and storytelling among her forms.","The Hindi sequence presented under Prahar uses short, sharply turned sections to question comfort, power and the expectations placed on women. Violence first appears as the quiet cultivation of endless desire; another section challenges the complacency of pity offered from privilege. The sequence then moves through womanhood and domestic freedom to an intimate act of self-preservation through self-love."],sources=[source('Sahitya Akademi — annual report 2015–16','https://sahitya-akademi.gov.in/aboutus/pdf/AR-2015-16%281%29.pdf','Names Veena Karamchandani among contemporary Sindhi women writers.','search_index_report_excerpt'),source('KSKV Kachchh University — Sindhi syllabus','https://kskvku.ac.in/NEP_Base_Syllabus/BA%28SINDHII%29%205%266.pdf','Sindhi poetry course includes Maau ji Saugaat by Veena Karamchandani.','opened_pdf_search_index_text'),source('Sindh Courier — interview on female Sindhi writers','https://sindhcourier.com/female-sindhi-writers-have-been-shaping-the-literary-landscape-of-india/','Nari Lachhwani identifies Veena Karamchandani with Jaipur.','search_index_interview_excerpt')],identity_match='Captured biography itself uses Karamchandani; Jaipur and Sindhi/Hindi literary context match published spelling variant. Display name preserved.',poems_read=[dict(id=667,title='प्रहार',coverage='Complete original Hindi sequence, including अपराध, स्त्री, आज़ादी and प्यार',basis='Desire as concealed assault, privilege and pity, woman as book, unpaid domestic work and self-love.')],limitations=['No solo book publication details verified; university inclusion is not represented as a separate authored book.','Unrelated administrative/private records excluded.'],search_queries=['"Veena Karamchandani" poet Sindhi','"Veena Karamchandani" Jaipur books','"वीणा करमचंदानी" पुस्तक'],next_action='Author/editor to confirm preferred spelling and bibliography.'))
